package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Sheep;
import net.minecraft.world.entity.ambient.Bat;
import net.minecraft.world.phys.Vec3;
import static io.github.campione01.mineclientbridge.LocalSegmentEngineChecks.*;
/** Production reader/controller tests, synthetic loaded entities and ordinary pose samples. */
public final class RouteStopEngineChecks {
 static int assertions;static JsonArray cases=new JsonArray();
 static void ok(boolean b,String why){assertions++;if(!b)throw new AssertionError(why);}
 static void scenario(String name,Runnable r){r.run();cases.add(name);System.out.println("PASS "+name);}
 static ClientActionRequest.Rejected refused(Runnable r){assertions++;try{r.run();}catch(ClientActionRequest.Rejected e){return e;}throw new AssertionError("Expected refusal");}
 static Minecraft environment(){ScopedLocalSegmentDispatch.nextTick();Hooks.reset();ClientActions.reset();MovementBudget.active=false;WorldGeneration.value="world";IntegratedServerIdentity.value="server";NavigationPositionGuard.value=0;BridgeServer.held=false;NativeLivingObservation.reset();Minecraft mc=new Minecraft();ScopedLocalSegmentDispatch.beforeMove(mc.player,MoverType.SELF,mc.player.velocity);return mc;}
 static <T extends Entity>T at(Minecraft mc,T e,int id,double x,double z){e.id=id;e.uuid=new UUID(0,id);e.x=e.tx=x;e.y=e.ty=1;e.z=e.tz=z;mc.level.entities.add(e);return e;}
 static F admit(Minecraft mc){var r=request(0);var m=new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time,false,true);m.admissionRecheck(mc);m.admissionRawFence(mc);var e=ClientActions.install(r,m);m.activate(e);return new F(mc,m,e,System.nanoTime());}
 static F start(){return admit(environment());}
 static void clean(F f){ok(!f.entry().result.has("route_threat_stop")&&!f.m().admissionThreat()&&!f.m().spatialThreatProfile(),"default never authorizes defense");}
 static void diagnostic(ClientActionRequest.Rejected e,String type,String phase){var d=e.response().getAsJsonObject("route_entity_rejection");ok(d!=null&&d.get("entity_type").getAsString().equals(type)&&d.get("phase").getAsString().equals(phase),"actual bounded diagnostic "+e.response());ok(d.keySet().equals(Set.of("schema_version","profile","policy","phase","entity_type","exception_type","rejection_code")),"closed diagnostic");ok(d.get("profile").getAsString().equals(ScopedRouteStopPolicy.PROFILE)&&!d.toString().contains("uuid"),"diagnostic no hidden identity");}
 static List<Entity> far(){return List.of(new net.minecraft.world.entity.ambient.Bat(),new net.minecraft.world.entity.animal.Cod(),new net.minecraft.world.entity.animal.Salmon(),new net.minecraft.world.entity.animal.TropicalFish(),new net.minecraft.world.entity.animal.Squid(),new net.minecraft.world.entity.GlowSquid(),new net.minecraft.world.entity.animal.Turtle(),new net.minecraft.world.entity.animal.Cat(),new net.minecraft.world.entity.animal.Ocelot(),new net.minecraft.world.entity.animal.Parrot(),new net.minecraft.world.entity.animal.horse.Horse(),new net.minecraft.world.entity.animal.horse.Donkey(),new net.minecraft.world.entity.animal.horse.Mule(),new net.minecraft.world.entity.npc.Villager(),new net.minecraft.world.entity.npc.WanderingTrader());}
 public static void main(String[] args)throws Exception{Path out=Path.of(args[0]);
  scenario("every-far-exact-passive-complete-geometry",()->{var mc=environment();int i=20;for(var e:far())at(mc,e,i++,20,20);var f=admit(mc);f.m().beforeEffect(mc);var g=f.m().facts().getAsJsonObject("entity_guard");ok(g.get("enumerated_count").getAsInt()==16&&g.getAsJsonArray("rows").size()==15,"full enumeration");for(var row:g.getAsJsonArray("rows")){var j=row.getAsJsonObject();ok(j.get("verdict").getAsString().equals("outside_context")&&j.has("velocity")&&j.has("aabb")&&j.has("lerp_target")&&j.has("projected_aabb"),"full far provenance");}clean(f);});
  scenario("original-passive-outside-body-inside-context",()->{var mc=environment();at(mc,new Sheep(),20,.5,2);var f=admit(mc);f.m().beforeEffect(mc);ok(f.m().facts().getAsJsonObject("entity_guard").getAsJsonArray("rows").get(0).getAsJsonObject().get("verdict").getAsString().equals("outside_swept"),"swept not terrain halo");clean(f);});
  scenario("legacy-and-threat-still-reject-far-bat",()->{var mc=environment();at(mc,new Bat(),20,20,20);var r=request(0);refused(()->new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time));var tr=SpatialThreatEngineChecks.request();refused(()->new ScopedLocalSegmentMovement(mc,tr,System.nanoTime(),mc.level.time,true));});
  scenario("new-far-class-inside-context-refused",()->{var mc=environment();at(mc,new Bat(),20,.5,2);diagnostic(refused(()->admit(mc)),"minecraft:bat","policy");ok(ClientActions.active==null,"refusal before ownership");});
  scenario("projected-far-crossing-and-touching-refused",()->{for(int k=0;k<3;k++){var mc=environment();var e=at(mc,new Bat(),20,k==2?4.3:20,.5);if(k==0)e.velocity=new Vec3(-.2,0,0);if(k==1)e.tx=.5;diagnostic(refused(()->admit(mc)),"minecraft:bat","policy");}});
  scenario("near-swept-projectile-body-and-touch-refused",()->{for(double z:new double[]{.5,1.200002}){var mc=environment();at(mc,new Sheep(),20,.5,z);refused(()->admit(mc));}});
  scenario("unknown-hazard-and-subclass-far-still-refused",()->{for(String kind:List.of("zombie","arrow","tnt","area_effect_cloud","pufferfish","dolphin","goat","wolf","fox","rabbit","unknown")){var mc=environment();var e=at(mc,new Entity(),20,1000,1000);e.type=new EntityType<>(kind);diagnostic(refused(()->admit(mc)),kind.contains(":")?"minecraft:"+kind:"minecraft:"+kind,"type");}var mc=environment();class ModBat extends Bat{}at(mc,new ModBat(),20,1000,1000);refused(()->admit(mc));});
  scenario("unknown-overridden-type-reader-not-invoked",()->{var mc=environment();class Unsafe extends Entity{public EntityType<?> getType(){throw new AssertionError("unknown getter invoked");}}at(mc,new Unsafe(),20,1000,1000);diagnostic(refused(()->admit(mc)),"type_unavailable","type");});
  scenario("finite-projection-identity-and-full-coverage",()->{for(int k=0;k<5;k++){var mc=environment();var b=at(mc,new Bat(),20,20,20);if(k==0)b.x=Double.NaN;if(k==1)b.velocity=new Vec3(Double.MAX_VALUE,0,0);if(k==2)mc.level.entities.add(b);if(k==3)at(mc,new Bat(),20,30,30);if(k==4)mc.level.entities.remove(mc.player);refused(()->admit(mc));}var mc=environment();for(int i=0;i<1024;i++)at(mc,new Bat(),20+i,20,20);refused(()->admit(mc));});
  scenario("far-state-target-fire-and-effects-refuse",()->{for(int k=0;k<3;k++){var mc=environment();var b=at(mc,new Bat(),20,20,20);if(k==0)b.target=mc.player;if(k==1)b.fireTicks=1;if(k==2)b.noPhysics=true;refused(()->admit(mc));}});
  scenario("removed-unknown-retained-without-shape",()->{var mc=environment();var b=at(mc,new Entity(),20,20,20);b.removed=true;var f=admit(mc);var g=f.m().facts().getAsJsonObject("entity_guard");ok(g.get("removed_count").getAsInt()==1&&g.getAsJsonArray("rows").get(0).getAsJsonObject().size()==5,"removed full identity");});
  scenario("same-callback-replacement-cannot-pass",()->{var mc=environment();var b=at(mc,new Bat(),20,20,20);var f=admit(mc);Hooks.once("friction",0,()->{mc.level.entities.remove(b);at(mc,new Bat(),20,20,20);});refused(()->f.m().beforeEffect(mc));clean(f);});
  scenario("reentrant-finished-or-replaced-owner-never-gets-late-diagnostic",()->{for(int k=0;k<4;k++){var mc=environment();at(mc,new Bat(),20,20,20);var f=admit(mc);int mode=k;var replacement=new ClientActions.RuntimeAction(new ActionRegistry.Entry(request(0)),null);String[] originalBytes={null},replacementBytes={replacement.entry.result.toString()};Hooks.once("friction",0,()->{if(mode!=2)ClientActions.finish(mode==1?"succeeded":"cancelled",mode==1?"path_reached":"cancel_requested");if(mode>=2)ClientActions.active=replacement;originalBytes[0]=f.entry().result.toString();at(mc,new Entity(),21,1000,1000);});var refused=refused(()->f.m().beforeEffect(mc));ok(refused.routeEntityRejection!=null,"late failure retains its diagnostic exception");ok(f.entry().result.toString().equals(originalBytes[0]),"original result bytes unchanged");ok(replacement.entry.result.toString().equals(replacementBytes[0]),"replacement result bytes unchanged");if(mode!=2)ok(f.entry().status.equals(mode==1?"succeeded":"cancelled")&&f.entry().reason.equals(mode==1?"path_reached":"cancel_requested"),"existing terminal unchanged");else ok(f.entry().running(),"original running status unchanged");if(mode>=2)ok(ClientActions.active==replacement,"replacement remains active");}});
  scenario("continuation-retains-diagnostic-without-defense",()->{var f=start();var e=at(f.mc(),new Entity(),20,1000,1000);e.type=new EntityType<>("arrow");var r=refused(()->f.m().beforeEffect(f.mc()));diagnostic(r,"minecraft:arrow","type");ok(f.entry().result.get("route_entity_rejection").equals(r.routeEntityRejection),"original receipt diagnostic");clean(f);});
  scenario("late-motion-unknown-is-not-promoted",()->{var f=start();f.m().markAttempted();at(f.mc(),new Entity(),20,1000,1000);ScopedLocalSegmentDispatch.arm(f.m());ok(!ScopedLocalSegmentDispatch.beforeMove(f.mc().player,MoverType.SELF,f.mc().player.velocity),"late refusal");ok(f.entry().result.get("unknown_outcome").getAsBoolean()&&f.entry().result.get("effect_outcome").getAsString().equals("unknown")&&f.entry().result.has("route_entity_rejection"),"unknown and diag retained");clean(f);});
  scenario("ordinary-intent-cannot-borrow-target-authority",()->{for(String k:List.of("route_threat_guard","route_stop_only")){var r=request(0);r.original().addProperty(k,true);refused(()->new ScopedLocalSegmentMovement(environment(),r,System.nanoTime(),100,false,true));}});
  scenario("unknown-exception-text-never-serialized",()->{var d=new RouteEntityDiagnostics();d.phase(RouteEntityDiagnostics.Phase.STATE);d.trustedType("minecraft:bat");var r=d.rejection(new IllegalStateException("secret arbitrary exception"));ok(!r.response().toString().contains("secret")&&r.response().get("error").getAsString().equals("scoped_movement_entity_coverage_unknown"),"bounded exception");});
  var mc=environment();int id=20;for(Entity e:far())at(mc,e,id++,20,20);at(mc,new Sheep(),50,.5,2);var success=admit(mc);sample(success,1,.8,1,true,-.0784,0);sample(success,2,1.1,1,true,-.0784,0);sample(success,3,1.4,1,true,-.0784,0);sample(success,4,1.47,1,true,-.0784,0);success.m().markAttempted();writeFixture(out.resolve("route-stop-success"),success);
  var rejection=start();var bad=at(rejection.mc(),new Entity(),20,1000,1000);bad.type=new EntityType<>("arrow");var rejected=refused(()->rejection.m().beforeEffect(rejection.mc()));rejection.entry().status="cancelled";rejection.entry().reason=rejected.getMessage();writeFixture(out.resolve("route-stop-rejection"),rejection);var admissionMc=environment();var admissionBad=at(admissionMc,new Entity(),20,1000,1000);admissionBad.type=new EntityType<>("arrow");var admissionRejected=refused(()->admit(admissionMc));ok(ClientActions.active==null,"exported admission never registers");Files.writeString(out.resolve("admission-rejection.json"),BridgeJson.toJson(admissionRejected.response()),StandardOpenOption.CREATE_NEW);
  var motion=start();motion.m().markAttempted();at(motion.mc(),new Entity(),20,1000,1000);ScopedLocalSegmentDispatch.arm(motion.m());ScopedLocalSegmentDispatch.beforeMove(motion.mc().player,MoverType.SELF,motion.mc().player.velocity);writeFixture(out.resolve("route-stop-motion"),motion);
  JsonObject report=new JsonObject();report.addProperty("assertions",assertions);report.add("cases",cases);report.addProperty("scope","Production native reader/controller with explicit synthetic readers; no loader, game or physics acceptance");Files.writeString(out.resolve("route-stop-result.json"),report.toString(),StandardOpenOption.CREATE_NEW);System.out.println("PASS assertions="+assertions);
 }
}
